import React from 'react';
import FaculltyOption from './FaculltyOption';
import Footer from '../footer';

const AboutFaculty = () => {
  return (
    <div className='relative bg-yellow-200 bg-opacity-80 h-[calc(100%-110px)] overflow-y-scroll'>

      <div>
        
      </div>

      <div>
        <div className='mt-[80px] text-center'>
          <h1 className='text-[30px] sm:text-3xl font-bold'>Our Skilled Faculties</h1>
          <p className='py-5 w-[90%] text-center ml-[80px] mt-[10px] text-[15px] sm:text-lg'>Patna Science Academy is proud to have a team of highly skilled and experienced faculties. They bring a wealth of knowledge and expertise to the classroom, ensuring our students receive top-quality education. With their passion for teaching and dedication to student success, our faculties create an engaging and supportive learning environment.</p>
        </div>

        <div className="mt-[60px] flex items-center justify-center flex-wrap">

          <FaculltyOption name="Mr. Hussain" designation="Organic Chemistry" source="https://w7.pngwing.com/pngs/329/705/png-transparent-teacher-student-education-tutor-faculty-teacher-class-expert-recruiter-thumbnail.png" />
        
          <FaculltyOption name="Mr. Hussain" designation="Organic Chemistry" source="https://w7.pngwing.com/pngs/329/705/png-transparent-teacher-student-education-tutor-faculty-teacher-class-expert-recruiter-thumbnail.png" />
        
          <FaculltyOption name="Mr. Hussain" designation="Organic Chemistry" source="https://w7.pngwing.com/pngs/329/705/png-transparent-teacher-student-education-tutor-faculty-teacher-class-expert-recruiter-thumbnail.png" />
        
          <FaculltyOption name="Mr. Hussain" designation="Organic Chemistry" source="https://w7.pngwing.com/pngs/329/705/png-transparent-teacher-student-education-tutor-faculty-teacher-class-expert-recruiter-thumbnail.png" />
        
          <FaculltyOption name="Mr. Hussain" designation="Organic Chemistry" source="https://w7.pngwing.com/pngs/329/705/png-transparent-teacher-student-education-tutor-faculty-teacher-class-expert-recruiter-thumbnail.png" />
        
          <FaculltyOption name="Mr. Hussain" designation="Organic Chemistry" source="https://w7.pngwing.com/pngs/329/705/png-transparent-teacher-student-education-tutor-faculty-teacher-class-expert-recruiter-thumbnail.png" />         
        
        </div>
      </div>

      <div className='h-[200px]'></div>

      <Footer />

    </div>
  );
};

export default AboutFaculty;
